def _slice_subtree_dur(row_id, children_of, seen=None):
    """递归求一个 slice 的子树 dur 之和 (仅 dur>=0 的子节点)。用于 dur<0 的 root 估算。"""
    if seen is None:
        seen = set()
    if row_id in seen:
        return 0
    seen.add(row_id)
    total = 0
    for child in children_of.get(row_id, []):
        cd = int(child.dur or 0)
        if cd >= 0:
            total += cd

